                                                                      ('20e18d0b841dc55d', 'a782a18c-b664-41c6-8a8c-9842393d3f4f', '345003be-0c7b-46a5-94c7-c7adff2ca74b', 'Формулы приведения для тупого угла', '2026-09-29 23:50:42.40839+00'),
                                                                      ('86d0d4fcc8866b01', 'a782a18c-b664-41c6-8a8c-9842393d3f4f', '573fb906-b33c-46f9-ab5e-3c6573b3da70', 'Угол между касательной и хордой', '2026-09-29 23:50:42.411066+00'),
                                                                      ('977aafecd90380d9', 'a782a18c-b664-41c6-8a8c-9842393d3f4f', '0a91dcc0-84a3-494e-aef5-412552622fca', 'Построение трапеции по четырём сторонам', '2026-09-29 23:50:42.413721+00')
INSERT INTO public.cards (id, fact_id, kind, question, answer_text, explanation, source_quote, source_ref, created_at, updated_at) VALUES
                                                                                                                                       ('2a89de89-0bcb-47d8-adb1-b9a09e3e4991', 'f5657c7262f269c8', 'choice', 'Как в статье 1 определяется Российская Федерация — Россия?', 'Демократическое федеративное правовое государство с республиканской формой правления', 'Статья 1 Конституции РФ прямо определяет Россию как демократическое, федеративное и правовое государство с республиканской формой правления. Это совокупная формула статуса государства.', E'Статья 1.\n\nРоссийская Федерация - Россия есть демократическое федеративное правовое государство с республиканской формой правления', 'ОРГ Лекция по разделу 4, стр. 3', '2026-09-29 23:37:45.570518+00', '2026-09-29 23:37:45.570518+00'),
                                                                                                                                       ('400b2482-20b4-4b4d-92f7-aea8a05d565d', 'f5657c7262f269c8', 'boolean', 'Российская Федерация определена одновременно как демократическое, федеративное и правовое государство с республиканской формой правления.', 'true', 'В тексте статьи 1 перечислены признаки: демократическое, федеративное, правовое, с республиканской формой правления; все они указаны вместе.', E'Статья 1.\n\nРоссийская Федерация - Россия есть демократическое федеративное правовое государство с республиканской формой правления', 'ОРГ Лекция по разделу 4, стр. 3', '2026-09-29 23:37:45.579747+00', '2026-09-29 23:37:45.579747+00'),
                                                                                                                                       ('d6b86b0d-e286-4396-93f2-93aaa55816af', 'f5657c7262f269c8', 'input', 'Форма правления с выборностью населением главы государства (Президента) называется...', 'Республика', 'Определение из конспекта описывает форму правления с выборностью населением главы государства (Президента), что соответствует республике.', E'Статья 1.\n\nРоссийская Федерация - Россия есть демократическое федеративное правовое государство с республиканской формой правления', 'ОРГ Лекция по разделу 4, стр. 3', '2026-09-29 23:37:45.582276+00', '2026-09-29 23:37:45.582276+00'),
                                                                                                                                       ('a0e5d527-eb40-4c2e-a51b-85d9eac62fa8', '85bf495a9d5013c5', 'boolean', 'Это определение характеризует унитарное государство.', 'false', 'В определении указано объединение нескольких государственных образований в одно союзное государство, а не подчинение регионов центру без их самостоятельности.', 'Форма государственного устройства, при которой несколько государственных образований, обладающих определенной юридической и политической самостоятельностью, образуют одно союзное государство', 'ОРГ Лекция по разделу 4, стр. 4', '2026-09-29 23:37:45.584804+00', '2026-09-29 23:37:45.584804+00'),
                                                                                                                                       ('d7a96318-ef24-4306-816a-925a44864d1b', '85bf495a9d5013c5', 'input', 'О какой категории понятий идет речь: «несколько государственных образований… образуют одно союзное государство»?', 'форма государственного устройства', 'Речь идёт о способе территориальной организации государства, то есть о форме государственного устройства.', 'Форма государственного устройства, при которой несколько государственных образований, обладающих определенной юридической и политической самостоятельностью, образуют одно союзное государство', 'ОРГ Лекция по разделу 4, стр. 4', '2026-09-29 23:37:45.587278+00', '2026-09-29 23:37:45.587278+00'),
                                                                                                                                       ('de6bde93-276c-4cde-a530-2109d4065c9d', '412c8f4ca8f42236', 'choice', 'Какой тип республики характеризуется разделением должностей главы государства и главы правительства, утверждением правительства Президентом с одобрения парламента и ответственностью перед Президентом и парламентом?', 'Смешанная (Россия)', 'Таблица сопоставляет типы республик; строка со всеми признаками относится к смешанной (полупрезидентской) республике, где применяется модель России.', E'РОССИЯ – СМЕШАННАЯ\n(ПОЛУПРЕЗИДЕНТСКАЯ) РЕСПУБЛИКА', 'ОРГ Лекция по разделу 4, стр. 5', '2026-09-29 23:37:45.590016+00', '2026-09-29 23:37:45.590016+00'),
                                                                                                                                       ('b4ae6eda-a960-4a06-98fc-71293bd43c8d', '412c8f4ca8f42236', 'boolean', 'Для указанного набора признаков таблица относит страну к смешанной (полупрезидентской) республике.', 'true', 'В таблице для этого типа указано разделение должностей, утверждение правительством Президентом с одобрения парламента и ответственность перед Президентом и парламентом — всё это приведено в одной строке.', E'РОССИЯ – СМЕШАННАЯ\n(ПОЛУПРЕЗИДЕНТСКАЯ) РЕСПУБЛИКА', 'ОРГ Лекция по разделу 4, стр. 5', '2026-09-29 23:37:45.600628+00', '2026-09-29 23:37:45.600628+00'),
                                                                                                                                       ('0be31dfa-633b-4578-8f34-87c0c910e898', '1e9574510ffe61e9', 'boolean', 'Президент может досрочно распустить парламент.', 'true', 'В смешанной (полупрезидентской) республике президент не вправе досрочно распускать парламент. Это отличает её от некоторых других моделей, где такая возможность есть.', 'Президент не может распустить парламент', 'ОРГ Лекция по разделу 4, стр. 5', '2026-09-29 23:37:45.602812+00', '2026-09-29 23:37:45.602812+00'),
                                                                                                                                       ('1d86f3d1-8a2c-48e6-bceb-8d9397866748', 'f8033c1bff524d86', 'choice', 'На какой срок избирается Президент Российской Федерации?', '6 лет', 'Срок полномочий Президента РФ составляет 6 лет. Это фиксированный конституционный срок.', E'Срок полномочий – 6 лет\n\n\n\nПрезидентом Российской Федерации может быть избран гражданин Российской\nФедерации не моложе 35 лет, постоянно проживающий в Российской Федерации не менее 25 лет', 'ОРГ Лекция по разделу 4, стр. 7', '2026-09-29 23:37:45.604919+00', '2026-09-29 23:37:45.604919+00'),
                                                                                                                                       ('e00fd772-0577-432d-bd1b-2ee176b8862b', 'f8033c1bff524d86', 'input', 'Минимальный возраст для избрания Президентом РФ', '35 лет', 'Минимальный возраст кандидата на пост Президента РФ — 35 лет. Это одно из базовых требований к кандидату.', E'Срок полномочий – 6 лет\n\n\n\nПрезидентом Российской Федерации может быть избран гражданин Российской\nФедерации не моложе 35 лет, постоянно проживающий в Российской Федерации не менее 25 лет', 'ОРГ Лекция по разделу 4, стр. 7', '2026-09-29 23:37:45.614887+00', '2026-09-29 23:37:45.614887+00'),
                                                                                                                                       ('c80b339c-a254-47af-bb28-ca87874df7bc', 'f8033c1bff524d86', 'boolean', 'Кандидат в Президенты РФ должен постоянно проживать в России не более 25 лет.', 'false', 'Требуется постоянное проживание в РФ не менее 25 лет; формулировка «не более 25 лет» неверна.', E'Срок полномочий – 6 лет\n\n\n\nПрезидентом Российской Федерации может быть избран гражданин Российской\nФедерации не моложе 35 лет, постоянно проживающий в Российской Федерации не менее 25 лет', 'ОРГ Лекция по разделу 4, стр. 7', '2026-09-29 23:37:45.617503+00', '2026-09-29 23:37:45.617503+00'),
                                                                                                                                       ('d806f91a-f740-4f48-aca9-0088d234e0a5', '35f199f62b4df265', 'choice', 'Ключевое полномочие Правительства РФ по бюджету', 'Разработка и представление федерального бюджета и обеспечение его исполнения', 'Правительство разрабатывает и представляет бюджет Федеральному собранию и обеспечивает его исполнение.', 'Разработка и представление Федеральному собранию федерального бюджета и обеспечение его исполнения; предоставление Государственной Думе отчёта об исполнении федерального бюджета Государственный (федеральный) бюджет формируется путём налогов и сборов, доходов от государственной собственности и др', 'ОРГ Лекция по разделу 4, стр. 9', '2026-09-29 23:37:45.619616+00', '2026-09-29 23:37:45.619616+00'),
                                                                                                                                       ('7fc8eda9-8d51-4fb9-a27c-2813c6180bb3', '35f199f62b4df265', 'boolean', 'Правительство предоставляет отчёт об исполнении бюджета Совету Федерации.', 'false', 'Отчёт об исполнении предоставляется Государственной Думе, а не Совету Федерации.', 'Разработка и представление Федеральному собранию федерального бюджета и обеспечение его исполнения; предоставление Государственной Думе отчёта об исполнении федерального бюджета Государственный (федеральный) бюджет формируется путём налогов и сборов, доходов от государственной собственности и др', 'ОРГ Лекция по разделу 4, стр. 9', '2026-09-29 23:37:45.629494+00', '2026-09-29 23:37:45.629494+00'),
                                                                                                                                       ('2d05d4f3-de9e-404d-b025-791d2a69fd33', '9aecec319523490d', 'choice', 'Какие органы проводят единую финансовую, кредитную и денежную политику в РФ?', 'Министерство финансов, Центральный банк', 'Единую финансовую, кредитную и денежную политику проводят Министерство финансов и Центральный банк наряду с другими структурами.', E'Государственный (федеральный) бюджет формируется путём налогов и сборов, доходов от государственной собственности и др.\nОбеспечение проведения в РФ единой финансовой, кредитной и денежной политики Политику проводят Министерство финансов, Центральный банк, другие структуры Осуществление управления федеральной собственностью Управление осуществляют министерства, государственные корпорации', 'ОРГ Лекция по разделу 4, стр. 9', '2026-09-29 23:37:45.63165+00', '2026-09-29 23:37:45.63165+00'),
                                                                                                                                       ('e686899e-5315-499e-9cd7-0336e18f8f7b', '9aecec319523490d', 'boolean', 'Управление федеральной собственностью осуществляют министерства и государственные корпорации.', 'true', 'В тексте указано, что управление федеральной собственностью осуществляют министерства и государственные корпорации.', E'Государственный (федеральный) бюджет формируется путём налогов и сборов, доходов от государственной собственности и др.\nОбеспечение проведения в РФ единой финансовой, кредитной и денежной политики Политику проводят Министерство финансов, Центральный банк, другие структуры Осуществление управления федеральной собственностью Управление осуществляют министерства, государственные корпорации', 'ОРГ Лекция по разделу 4, стр. 9', '2026-09-29 23:37:45.641971+00', '2026-09-29 23:37:45.641971+00'),
                                                                                                                                       ('68c16ea7-6ad6-473a-b345-1c3188b958ce', '7e4c5cba57870552', 'choice', 'По какой избирательной системе формируется Государственная Дума?', 'Смешанная избирательная система', 'Государственная Дума формируется по смешанной системе: половина депутатов избирается по мажоритарной, половина — по пропорциональной.', E'Государственная Дума\n(председатель – Вячеслав Викторович\nВолодин)\nФормирование: смешанная избирательная система (225 депутатов – избираются по мажоритарной системе, 225 – по пропорциональной системе)\n\nСовет Федерации\n(глава – Валентина Ивановна Матвиенко)\nФормирование: по 2 представителя от каждого субъекта РФ + не менее 10% представителей Президента РФ', 'ОРГ Лекция по разделу 4, стр. 10', '2026-09-29 23:37:45.644111+00', '2026-09-29 23:37:45.644111+00'),
                                                                                                                                       ('ab6c395f-0bcd-4d54-b3b9-83c888ed51df', '7e4c5cba57870552', 'input', 'Сколько депутатов Государственной Думы избираются по мажоритарной системе?', '225', 'Половина состава Государственной Думы — 225 депутатов — избирается по мажоритарной системе.', E'Государственная Дума\n(председатель – Вячеслав Викторович\nВолодин)\nФормирование: смешанная избирательная система (225 депутатов – избираются по мажоритарной системе, 225 – по пропорциональной системе)\n\nСовет Федерации\n(глава – Валентина Ивановна Матвиенко)\nФормирование: по 2 представителя от каждого субъекта РФ + не менее 10% представителей Президента РФ', 'ОРГ Лекция по разделу 4, стр. 10', '2026-09-29 23:37:45.653968+00', '2026-09-29 23:37:45.653968+00'),
                                                                                                                                       ('7da1fdda-33e6-4b1b-aab0-e1d7f8e9d411', '7e4c5cba57870552', 'flip', 'Как формируется Совет Федерации?', 'по 2 представителя от каждого субъекта РФ + не менее 10% представителей Президента РФ', 'Совет Федерации формируется из двух представителей от каждого субъекта РФ и не менее 10% представителей Президента РФ.', E'Государственная Дума\n(председатель – Вячеслав Викторович\nВолодин)\nФормирование: смешанная избирательная система (225 депутатов – избираются по мажоритарной системе, 225 – по пропорциональной системе)\n\nСовет Федерации\n(глава – Валентина Ивановна Матвиенко)\nФормирование: по 2 представителя от каждого субъекта РФ + не менее 10% представителей Президента РФ', 'ОРГ Лекция по разделу 4, стр. 10', '2026-09-29 23:37:45.656096+00', '2026-09-29 23:37:45.656096+00'),
                                                                                                                                       ('953e6ff5-0803-4087-afa9-001bbcd1aa51', 'e2ad1e2979660853', 'choice', 'Какое полномочие относится к ведению Государственной Думы?', 'Дача согласия Президенту на назначение Председателя Правительства', 'Среди полномочий Государственной Думы названа дача согласия Президенту на назначение Председателя Правительства.', E'Полномочия Государственной Думы\nа) дача согласия Президенту Российской Федерации на назначение Председателя Правительства Российской Федерации;\nб) решение вопроса о доверии Правительству Российской Федерации;\nв) заслушивание ежегодных отчетов Правительства Российской Федерации о результатах его деятельности, в том числе по вопросам, поставленным Государственной Думой;\nг) назначение на должность и освобождение от должности Председателя Центрального банка Российской Федерации', 'ОРГ Лекция по разделу 4, стр. 11', '2026-09-29 23:37:45.658189+00', '2026-09-29 23:37:45.658189+00'),
                                                                                                                                       ('46320b6b-e2e4-41cc-8cf1-21ac840ff42b', 'e2ad1e2979660853', 'flip', 'Назовите одно из полномочий Государственной Думы, связанное с контролем деятельности Правительства.', 'решение вопроса о доверии Правительству', 'Одним из полномочий Государственной Думы является решение вопроса о доверии Правительству РФ.', E'Полномочия Государственной Думы\nа) дача согласия Президенту Российской Федерации на назначение Председателя Правительства Российской Федерации;\nб) решение вопроса о доверии Правительству Российской Федерации;\nв) заслушивание ежегодных отчетов Правительства Российской Федерации о результатах его деятельности, в том числе по вопросам, поставленным Государственной Думой;\nг) назначение на должность и освобождение от должности Председателя Центрального банка Российской Федерации', 'ОРГ Лекция по разделу 4, стр. 11', '2026-09-29 23:37:45.668166+00', '2026-09-29 23:37:45.668166+00'),
                                                                                                                                       ('a7738b2a-187d-411b-a793-ca1b1df5e49b', 'e2ad1e2979660853', 'boolean', 'В конспекте подробно перечислены полномочия Совета Федерации.', 'false', 'Полномочия Совета Федерации в приведённом фрагменте не раскрыты, поэтому утверждение неверно применительно к тексту.', E'Полномочия Государственной Думы\nа) дача согласия Президенту Российской Федерации на назначение Председателя Правительства Российской Федерации;\nб) решение вопроса о доверии Правительству Российской Федерации;\nв) заслушивание ежегодных отчетов Правительства Российской Федерации о результатах его деятельности, в том числе по вопросам, поставленным Государственной Думой;\nг) назначение на должность и освобождение от должности Председателя Центрального банка Российской Федерации', 'ОРГ Лекция по разделу 4, стр. 11', '2026-09-29 23:37:45.670513+00', '2026-09-29 23:37:45.670513+00'),
                                                                                                                                       ('b66d0b99-e316-469d-9a3a-9ea54e425bdb', '4cdd871c3f6ed589', 'boolean', 'Совет Федерации утверждает указ Президента Российской Федерации о введении военного положения.', 'true', 'Среди перечисленных полномочий прямо названо утверждение указов Президента о введении военного положения.', E'а) утверждение изменения границ между субъектами Российской Федерации;\nб) утверждение указа Президента Российской Федерации о введении военного положения;\nв) утверждение указа Президента Российской Федерации о введении чрезвычайного положения;\nг) решение вопроса о возможности использования Вооруженных Сил Российской Федерации за пределами территории Российской Федерации;\nд) назначение выборов Президента Российской Федерации;\nе) отрешение Президента Российской Федерации от должности', 'ОРГ Лекция по разделу 4, стр. 11', '2026-09-29 23:37:45.672599+00', '2026-09-29 23:37:45.672599+00'),
                                                                                                                                       ('df7bee8f-7784-4d2a-a2b8-b5c915b203c5', 'f5a73b8d25bc4bb1', 'choice', 'Какова главная задача Конституционного суда согласно конспекту?', 'Отмена законов, противоречащих Конституции и нарушающих права граждан', 'Главная функция Конституционного суда — отменять законы, которые противоречат Конституции и нарушают права граждан.', E'Конституционный суд: отменяет законы, противоречащие Конституции и нарушающие права граждан\n\nВерховный суд: важнейший орган судебной власти по гражданским, уголовным и административным делам + верховные суды субъектов и городские Арбитражные суды: разрешают экономические споры между гражданами, занимающимися предпринимательской деятельностью и организациями', 'ОРГ Лекция по разделу 4, стр. 12', '2026-09-29 23:37:45.674812+00', '2026-09-29 23:37:45.674812+00'),
                                                                                                                                       ('0ef80e78-6d23-46a9-8849-d01808e83207', 'f5a73b8d25bc4bb1', 'boolean', 'Верховный суд разрешает экономические споры между гражданами, занимающимися предпринимательской деятельностью, и организациями.', 'false', 'Разрешение экономических споров между гражданами-предпринимателями и организациями осуществляют арбитражные суды, а не Верховный суд.', E'Конституционный суд: отменяет законы, противоречащие Конституции и нарушающие права граждан\n\nВерховный суд: важнейший орган судебной власти по гражданским, уголовным и административным делам + верховные суды субъектов и городские Арбитражные суды: разрешают экономические споры между гражданами, занимающимися предпринимательской деятельностью и организациями', 'ОРГ Лекция по разделу 4, стр. 12', '2026-09-29 23:37:45.685825+00', '2026-09-29 23:37:45.685825+00'),
                                                                                                                                       ('f0c747ee-acae-421d-89f6-bc69ec2733c0', 'f5a73b8d25bc4bb1', 'input', 'Какие суды разрешают экономические споры между гражданами, занимающимися предпринимательской деятельностью, и организациями?', 'арбитражные суды', 'Экономические споры между гражданами, занимающимися предпринимательской деятельностью, и организациями разрешают арбитражные суды.', E'Конституционный суд: отменяет законы, противоречащие Конституции и нарушающие права граждан\n\nВерховный суд: важнейший орган судебной власти по гражданским, уголовным и административным делам + верховные суды субъектов и городские Арбитражные суды: разрешают экономические споры между гражданами, занимающимися предпринимательской деятельностью и организациями', 'ОРГ Лекция по разделу 4, стр. 12', '2026-09-29 23:37:45.687902+00', '2026-09-29 23:37:45.687902+00'),
                                                                                                                                       ('b6680ec9-18f8-424a-8326-491bce91e73b', 'a05bb543f6b15b36', 'choice', 'Какой орган представляет законодательную власть на федеральном уровне в России?', 'Федеральное Собрание', 'Законодательную власть на федеральном уровне осуществляет Федеральное Собрание.', E'Основы российской государственности\n# Ветви и уровни власти в России\n\n## Законодательная власть\n\n### Федеральный уровень\nФедеральное Собрание\n\n### Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)', 'ОРГ Лекция по разделу 4, стр. 12–13', '2026-09-29 23:37:45.689918+00', '2026-09-29 23:37:45.689918+00'),
                                                                                                                                       ('f9376ea8-5033-4b3c-a314-aa561b0f9f6f', 'a05bb543f6b15b36', 'boolean', 'Президент РФ обладает особым статусом в системе федеральной исполнительной власти.', 'true', 'В тексте сказано, что Президент РФ имеет особый статус в системе исполнительной власти федерального уровня.', E'Основы российской государственности\n# Ветви и уровни власти в России\n\n## Законодательная власть\n\n### Федеральный уровень\nФедеральное Собрание\n\n### Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)', 'ОРГ Лекция по разделу 4, стр. 12–13', '2026-09-29 23:37:45.697846+00', '2026-09-29 23:37:45.697846+00'),
                                                                                                                                       ('e760f80f-c07b-4063-9bf4-760e3a444250', '48d3b95802b6f8e9', 'boolean', 'Городской районный суд рассматривает гражданские, уголовные и административные дела незначительной сложности.', 'true', 'В тексте говорится, что городской районный суд рассматривает дела незначительной сложности.', E'городские районные суды\n\nрассматривают гражданские, уголовные, административные дела незначительной сложности', 'ОРГ Лекция по разделу 4, стр. 12', '2026-09-29 23:37:45.700033+00', '2026-09-29 23:37:45.700033+00'),
                                                                                                                                       ('d887474f-56e1-4126-9117-555f40447280', 'c81fb171b3f196cf', 'choice', 'Какой орган является высшим законодательным органом субъекта РФ на примере Пермского края?', 'Законодательное Собрание Пермского края', 'На региональном уровне законодательную власть представляет Законодательное Собрание. Городские Думы и Земские Собрания относятся к муниципальному уровню.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.702337+00', '2026-09-29 23:37:45.702337+00'),
                                                                                                                                       ('d65e4bb6-7bc2-4011-b394-c3fa005c1cff', 'c81fb171b3f196cf', 'boolean', 'Все субъекты Российской Федерации имеют равные права во взаимоотношениях с федеральными органами государственной власти.', 'true', 'В тексте сказано, что все субъекты независимо от вида обладают равными правами во взаимоотношениях с федеральными органами государственной власти.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.710032+00', '2026-09-29 23:37:45.710032+00'),
                                                                                                                                       ('dc1c0cf4-27b2-476b-a8fa-ed51381a9081', 'ca565456b0a34c47', 'choice', 'Кто возглавляет систему органов исполнительной власти на уровне Пермского края?', 'Губернатор Пермского края', 'На региональном уровне исполнительную власть возглавляет Губернатор. Председатель Правительства РФ относится к федеральному уровню, главы муниципальных образований — к муниципальному.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края\nГубернатор Пермского края\nПравительство Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.712465+00', '2026-09-29 23:37:45.712465+00'),
                                                                                                                                       ('063fb79e-6c7d-4aec-ba55-8e61c8af5526', 'ca565456b0a34c47', 'boolean', 'Субъекту федерации запрещено формировать собственные органы исполнительной и судебной власти.', 'false', 'В перечне признаков есть пункт о наличии у субъекта собственной системы органов исполнительной и судебной власти.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края\nГубернатор Пермского края\nПравительство Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.722852+00', '2026-09-29 23:37:45.722852+00'),
                                                                                                                                       ('80c5b24c-ccec-4cc5-bf9a-65b9025e9fc5', '79f739323c48223f', 'choice', 'Какой суд общей юрисдикции указан как судебный орган регионального уровня для Пермского края?', 'Пермский краевой суд', 'К региональному уровню судов отнесён Пермский краевой суд. Арбитражный апелляционный суд выходит за рамки одного субъекта; Конституционный Суд РФ — федеральный уровень.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края\nГубернатор Пермского края\nПравительство Пермского края\nПермский краевой суд\nАрбитражный суд Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.724909+00', '2026-09-29 23:37:45.724909+00'),
                                                                                                                                       ('b4f5ea44-9093-43e0-b57e-b8f9a70c8adb', '79f739323c48223f', 'boolean', 'Для Пермского края указаны судебные органы регионального уровня.', 'true', 'В разделе «Судебная власть» перечислены суды регионального уровня, включая Пермский краевой суд и Арбитражный суд Пермского края.', E'Региональный уровень (Пермский край)\n[неразборчиво]\n\n---\n\n## Исполнительная власть\n\n### Федеральный уровень\nПрезидент РФ (особый статус)\nПравительство РФ\n\n---\n\n## Судебная власть\n\n### Федеральный уровень\nСуды высшей инстанции\nРЕГИОНАЛЬНЫЙ УРОВЕНЬ (ПЕРМСКИЙ КРАЙ)\nЗаконодательное Собрание Пермского края\nГубернатор Пермского края\nПравительство Пермского края\nПермский краевой суд\nАрбитражный суд Пермского края', 'ОРГ Лекция по разделу 4, стр. 13', '2026-09-29 23:37:45.732785+00', '2026-09-29 23:37:45.732785+00'),
                                                                                                                                       ('b6a4d100-d7a9-4efc-9961-2dadbe6f041a', 'd7657dfe21193b1f', 'boolean', 'Субъекты Российской Федерации имеют право выхода из состава федерации.', 'true', 'В пункте 7 явно зафиксировано отсутствие у субъектов права сецессии — выхода из состава федерации.', '7) отсутствие у субъектов федерации права сецессии – выхода из состава федерации', 'ОРГ Лекция по разделу 4, стр. 14', '2026-09-29 23:37:45.734918+00', '2026-09-29 23:37:45.734918+00'),
                                                                                                                                       ('756fe215-acbe-4d8f-8c0d-dc220f9abcc9', 'eaec1c960b7d5682', 'choice', 'Как называется первая фаза трансляции кода на C++?', 'Препроцессор', 'Препроцессор — это первая фаза трансляции, которая обрабатывает директивы и подготавливает код к компиляции.', 'Препроцессор - первая фаза трансляции', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 5', '2026-09-29 23:43:01.636966+00', '2026-09-29 23:43:01.636966+00'),
                                                                                                                                       ('abc0dbbf-2c14-4198-973e-7ab74aadba32', 'eaec1c960b7d5682', 'boolean', 'Директивы препроцессора всегда начинаются с символа #.', 'true', 'В тексте прямо указано: «Директивы начинаются с символа ''#''». Это является их отличительным признаком в языке C++.', 'Препроцессор - первая фаза трансляции', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 5', '2026-09-29 23:43:01.651845+00', '2026-09-29 23:43:01.651845+00'),
                                                                                                                                       ('a955e110-97a0-4ee6-ad39-8ac81f896b64', 'eaec1c960b7d5682', 'flip', 'Что такое макросы для препроцессора?', 'Макросы - это идентификаторы, которые препроцессор заменяет другими фрагментами кода или значениями до начала компиляции программы.', 'Это определение из конспекта. Препроцессор выполняет простую текстовую замену макросов-идентификаторов перед тем, как код поступит на вход компилятора.', 'Препроцессор - первая фаза трансляции', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 5', '2026-09-29 23:43:01.655223+00', '2026-09-29 23:43:01.655223+00'),
                                                                                                                                       ('2ff01d3b-6f3c-4a5f-82c7-a2631b12b725', '1d0992a7c1801c88', 'boolean', 'Заголовочные файлы могут содержать определения функций и данных.', 'false', 'Согласно тексту, в заголовочном файле не должно быть определений функций и данных; всё это описывается в соответствующем .cpp файле.', 'В заголовочном файле не должно быть определений функций и данных. Всё это должно быть описано в соответствующем .cpp файле', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 8', '2026-09-29 23:43:01.65771+00', '2026-09-29 23:43:01.65771+00'),
                                                                                                                                       ('ae022fa4-eabd-41ef-8699-6d8bd7f633fe', '1d0992a7c1801c88', 'flip', 'Какое правило размещения кода между заголовочными и cpp-файлами приведено во фрагменте?', 'В заголовочном файле не должно быть определений функций и данных.', 'Правило разделения интерфейса и реализации: заголовок задаёт интерфейс (объявления), а реализация размещается в .cpp-файле.', 'В заголовочном файле не должно быть определений функций и данных. Всё это должно быть описано в соответствующем .cpp файле', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 8', '2026-09-29 23:43:01.660292+00', '2026-09-29 23:43:01.660292+00'),
                                                                                                                                       ('9dfd2b9d-5435-46f3-abc7-bfd297ccf873', '53053c791d3379d1', 'choice', 'На какое число будет заменена лексема pi после работы препроцессора в примере?', '4', 'По определению pi заменяется на 4. Подстановка происходит до вычислений, поэтому значение pi равно 4.', 'В данном коде pi заменится на 4, а все вхождения r - на 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 11', '2026-09-29 23:43:01.662849+00', '2026-09-29 23:43:01.662849+00'),
                                                                                                                                       ('aaccb9a2-d869-48e5-97d1-1f97755b0412', '53053c791d3379d1', 'boolean', 'При замене макроса r на 2 учитывается приоритет умножения, чтобы получить одно число 2 вместо трёх отдельных чисел.', 'false', 'В примере показано прямое текстовое замещение без учёта приоритета операций: каждое r заменяется на 2, образуя выражение 4 * 2 * 2.', 'В данном коде pi заменится на 4, а все вхождения r - на 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 11', '2026-09-29 23:43:01.671661+00', '2026-09-29 23:43:01.671661+00'),
                                                                                                                                       ('00dae7e7-a66e-4d3b-b19d-007608415ffa', '53053c791d3379d1', 'flip', 'Почему при использовании #define r 2 выражение со всеми вхождениями r превращается в 4 * 2 * 2?', 'Замена каждого вхождения идентификатора r на 2 приводит к выражению 4 * 2 * 2.', 'Препроцессор делает простую текстовую подстановку: все токены r заменяются на 2, формируя последовательность множителей.', 'В данном коде pi заменится на 4, а все вхождения r - на 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 11', '2026-09-29 23:43:01.673848+00', '2026-09-29 23:43:01.673848+00'),
                                                                                                                                       ('12167ad8-4fc0-4002-8c9b-1419bb21c5d3', 'f2d6eb76b84560bd', 'boolean', 'Запись for(int i = 0, i < n, i++) cout (i, '' '') является синтаксически корректной.', 'false', 'Во фрагменте этот пример явно помечен как неверная запись из-за ошибок в пунктуации и операторах.', E'Верная запись: for(int i = 0; i < n; i++) { cout ѕ i ѕ '' ''; }\n▶\n\nНеверная запись: for(int i = 0, i < n, i++) cout (i, '' '')', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 3', '2026-09-29 23:43:01.67612+00', '2026-09-29 23:43:01.67612+00'),
                                                                                                                                       ('6b2e156d-6bf1-4c8e-8874-e530be595514', 'f2d6eb76b84560bd', 'flip', 'Для чего служат синтаксические определения в описании языка?', 'Синтаксические определения устанавливают правила построения элементов языка.', 'Это прямая формулировка из конспекта о назначении синтаксических определений.', E'Верная запись: for(int i = 0; i < n; i++) { cout ѕ i ѕ '' ''; }\n▶\n\nНеверная запись: for(int i = 0, i < n, i++) cout (i, '' '')', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 3', '2026-09-29 23:43:01.678247+00', '2026-09-29 23:43:01.678247+00'),
                                                                                                                                       ('45c0a9e4-103a-47d8-af2b-03e19fadf0d2', 'f2d6eb76b84560bd', 'flip', 'Какая пунктуационная ошибка допущена в неверной записи цикла for?', 'Точка с запятой должна разделять выражения в заголовке цикла for.', 'В ошибочной записи использованы запятые вместо точек с запятой, что нарушает синтаксис for в C++.', E'Верная запись: for(int i = 0; i < n; i++) { cout ѕ i ѕ '' ''; }\n▶\n\nНеверная запись: for(int i = 0, i < n, i++) cout (i, '' '')', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 3', '2026-09-29 23:43:01.680509+00', '2026-09-29 23:43:01.680509+00'),
                                                                                                                                       ('c25105d3-d1c1-40c1-ad38-ee251d57d6e4', '2fb258da7ca6fac5', 'choice', 'Какие минимальные смысловые единицы языка идут сразу после алфавита в иерархии состава языка?', 'Лексемы', 'В конспекте сказано: «Слова — токены (лексемы), минимальные единицы, имеющие смысл», то есть они следуют за алфавитом.', E'1. Алфавит - символы языка.\n(A-z, 0-9, спец. символы, пробельные символы)\n\n2. Слова - токены (лексемы), минимальные единицы, имеющие смысл.\n(for, int, "hello 3.1415, ==)\n\n3. Словосочетания - выражения.\n(3 + 2, isGood == true)\n\n4. Предложения - операторы', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 2', '2026-09-29 23:43:01.682742+00', '2026-09-29 23:43:01.682742+00'),
                                                                                                                                       ('4ef9731b-3bc4-4a0f-88cf-088db613143c', '2fb258da7ca6fac5', 'boolean', 'После слов (токенов) в составе языка следуют выражения.', 'true', 'Цепочка уровней дана последовательно: символы → лексемы → выражения → операторы.', E'1. Алфавит - символы языка.\n(A-z, 0-9, спец. символы, пробельные символы)\n\n2. Слова - токены (лексемы), минимальные единицы, имеющие смысл.\n(for, int, "hello 3.1415, ==)\n\n3. Словосочетания - выражения.\n(3 + 2, isGood == true)\n\n4. Предложения - операторы', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 2', '2026-09-29 23:43:01.692891+00', '2026-09-29 23:43:01.692891+00'),
                                                                                                                                       ('0d7f55d6-f9a4-497f-a3b6-52c076e9fd2b', '2fb258da7ca6fac5', 'flip', 'Что образует первый уровень состава языка согласно фрагменту?', 'Символы языка составляют его алфавит.', 'Первый уровень состава языка — алфавит, определяемый через наборы символов.', E'1. Алфавит - символы языка.\n(A-z, 0-9, спец. символы, пробельные символы)\n\n2. Слова - токены (лексемы), минимальные единицы, имеющие смысл.\n(for, int, "hello 3.1415, ==)\n\n3. Словосочетания - выражения.\n(3 + 2, isGood == true)\n\n4. Предложения - операторы', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 2', '2026-09-29 23:43:01.695066+00', '2026-09-29 23:43:01.695066+00'),
                                                                                                                                       ('067c35b0-e930-47ee-aacd-9c1a2eb5c2f3', '2fb258da7ca6fac5', 'choice', 'Какой элемент находится на вершине указанной иерархии состава языка?', 'Операторы', 'Последний уровень представленной иерархии назван «Предложения — операторы» в схеме состава языка.', E'1. Алфавит - символы языка.\n(A-z, 0-9, спец. символы, пробельные символы)\n\n2. Слова - токены (лексемы), минимальные единицы, имеющие смысл.\n(for, int, "hello 3.1415, ==)\n\n3. Словосочетания - выражения.\n(3 + 2, isGood == true)\n\n4. Предложения - операторы', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 2', '2026-09-29 23:43:01.697285+00', '2026-09-29 23:43:01.697285+00'),
                                                                                                                                       ('eebaf68a-b338-49fe-9ec6-db7a37a7d84a', '5e660dd83d82d74d', 'boolean', 'Выражение sqr(2 + 1) при макросе #define sqr(x) (x * x) вычисляется как 9.', 'false', 'Макрос sqr(x) заменяет вхождение на (x * x), поэтому подстановка даёт (2 + 1 * 2 + 1), что равно 5, а не 9. Ошибка возникает из-за отсутствия скобок вокруг параметра и всего выражения.', 'Казалось бы, 3 ∗ 3 = 9, однако #define заменил строку sqr(2 + 1) на (2 + 1 * 2 + 1), что действительно равняется пяти', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 13', '2026-09-29 23:43:01.707254+00', '2026-09-29 23:43:01.707254+00'),
                                                                                                                                       ('10d13068-ab91-4c84-b700-ec20db3810c1', '5e660dd83d82d74d', 'choice', 'Какая директива создаёт макрос, выглядящий как функция?', '#define', 'Для создания функционально-подобного макроса используется директива #define с параметрами. Она выполняет текстовую подстановку до компиляции.', 'Казалось бы, 3 ∗ 3 = 9, однако #define заменил строку sqr(2 + 1) на (2 + 1 * 2 + 1), что действительно равняется пяти', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 13', '2026-09-29 23:43:01.709385+00', '2026-09-29 23:43:01.709385+00'),
                                                                                                                                       ('19d9bc1d-39e2-4ccc-bc6a-0f036556fc6b', '5e660dd83d82d74d', 'flip', 'Как реализуется макрос, который выглядит как функция?', 'текстовая подстановка тела макроса вместо вызова', 'Макросы вида #define F(p) … реализуются подстановкой текста: каждое вхождение F(...) буквально заменяется на тело с подставленными аргументами.', 'Казалось бы, 3 ∗ 3 = 9, однако #define заменил строку sqr(2 + 1) на (2 + 1 * 2 + 1), что действительно равняется пяти', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 13', '2026-09-29 23:43:01.719478+00', '2026-09-29 23:43:01.719478+00'),
                                                                                                                                       ('fd80269a-cc19-4de1-8aa3-4cb6d570750e', '3d2cc9592c83a179', 'choice', 'Какая директива удаляет макрос, заданный #define?', '#undef', 'Директива #undef удаляет ранее заданный через #define макрос; после неё имя перестаёт быть определённым.', 'Директива #undef удаляет макрос, заданный #define', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 16', '2026-09-29 23:43:01.721647+00', '2026-09-29 23:43:01.721647+00'),
                                                                                                                                       ('29da8037-d43c-4df0-b6b0-3031c637ae70', '3d2cc9592c83a179', 'boolean', 'Директива #undef удаляет макрос, заданный #define.', 'true', 'В тексте прямо сказано, что #undef удаляет макрос, заданный #define.', 'Директива #undef удаляет макрос, заданный #define', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 16', '2026-09-29 23:43:01.731817+00', '2026-09-29 23:43:01.731817+00'),
                                                                                                                                       ('3d0225f0-74e9-4e20-a7c3-0c9bd6c09450', '3d2cc9592c83a179', 'flip', 'Что делает директива #undef?', 'удаление определения макроса', '#undef отменяет определение имени, сделанное ранее директивой #define.', 'Директива #undef удаляет макрос, заданный #define', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 16', '2026-09-29 23:43:01.733907+00', '2026-09-29 23:43:01.733907+00'),
                                                                                                                                       ('42f17162-e98d-4452-b59f-f6940ee0b09f', '876e731f6e7a16bd', 'boolean', 'Ключ компилятора -DLOG соответствует директиве #define LOG.', 'true', 'Флаг -DNAME задаёт для компилятора то же самое, что и #define NAME в коде.', E'Определение в аргументах компилятора:\n▶ -DLOG соответствует #define LOG.\n▶ -DLOG_LEVEL=2 соответствует #define LOG_LEVEL 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 15', '2026-09-29 23:43:01.73613+00', '2026-09-29 23:43:01.73613+00'),
                                                                                                                                       ('2bcc2942-8c7f-4e8f-b656-712ff9816c26', '876e731f6e7a16bd', 'choice', 'Какой ключ компилятора соответствует #define LOG_LEVEL 2?', '-DLOG_LEVEL=2', 'По тексту ключ -DLOG_LEVEL=2 эквивалентен #define LOG_LEVEL 2.', E'Определение в аргументах компилятора:\n▶ -DLOG соответствует #define LOG.\n▶ -DLOG_LEVEL=2 соответствует #define LOG_LEVEL 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 15', '2026-09-29 23:43:01.738485+00', '2026-09-29 23:43:01.738485+00'),
                                                                                                                                       ('ca576adc-777e-48ef-bb32-9ad83e800996', '876e731f6e7a16bd', 'flip', 'Что делает опция компилятора -DNAME?', 'определение символа препроцессора', 'Опция -D определяет символ препроцессора так же, как это делает #define.', E'Определение в аргументах компилятора:\n▶ -DLOG соответствует #define LOG.\n▶ -DLOG_LEVEL=2 соответствует #define LOG_LEVEL 2', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 15', '2026-09-29 23:43:01.748655+00', '2026-09-29 23:43:01.748655+00'),
                                                                                                                                       ('35062f0a-a2a7-4856-8edf-39e7a4b79408', 'b0c0ce918a949cd1', 'boolean', 'Каждая директива #if/#ifdef/#ifndef должна соответствовать закрывающей директиве #endif.', 'true', 'Текст указывает, что каждая условная директива должна иметь закрывающую #endif.', 'Каждая директива #if #ifdef #ifndef в исходном файле должна соответствовать закрывающей директиве #endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.751042+00', '2026-09-29 23:43:01.751042+00'),
                                                                                                                                       ('657ef3ca-a1c2-4e2f-85be-1390b6cb1bb7', 'b0c0ce918a949cd1', 'choice', 'Какая директива закрывает блок условной компиляции?', '#endif', 'Блок условной компиляции завершается директивой #endif.', 'Каждая директива #if #ifdef #ifndef в исходном файле должна соответствовать закрывающей директиве #endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.75321+00', '2026-09-29 23:43:01.75321+00'),
                                                                                                                                       ('9e13c90e-32ca-430f-b384-e796f20fd3bf', 'b0c0ce918a949cd1', 'flip', 'Зачем нужны директивы условной компиляции #if/#ifdef/#ifndef/…?', 'управляют включением частей исходного файла в компиляцию', 'Условные директивы включают или исключают фрагменты кода до компиляции в зависимости от условий.', 'Каждая директива #if #ifdef #ifndef в исходном файле должна соответствовать закрывающей директиве #endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.761709+00', '2026-09-29 23:43:01.761709+00'),
                                                                                                                                       ('19c6dc9d-4df4-4f66-847c-629626559e7b', 'b73a84868e5f6394', 'boolean', 'Между #if-цепочкой и #endif может быть не более одной директивы #else.', 'true', 'В тексте указано, что допускается не более одной директивы #else перед #endif.', E'допускается не более одной директивы #else.\n▶ Директива #else должна быть последней директивой перед\n#endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.763819+00', '2026-09-29 23:43:01.763819+00'),
                                                                                                                                       ('2b0d8684-00ce-49c4-8f8c-e73525adc330', 'b73a84868e5f6394', 'choice', 'Какая директива выполняется, если предыдущие условные директивы не сработали?', '#else', 'Если ни одно из предыдущих условий не сработало, выполняется ветка #else.', E'допускается не более одной директивы #else.\n▶ Директива #else должна быть последней директивой перед\n#endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.765891+00', '2026-09-29 23:43:01.765891+00'),
                                                                                                                                       ('3e05f91c-6f1f-4185-9ede-773a22de9183', 'b73a84868e5f6394', 'flip', 'Когда исполняется ветвь #else в цепочке условной компиляции?', 'когда все предшествующие условия ложны', '#else выбирается только тогда, когда ни одна из предыдущих ветвей цепочки не была включена.', E'допускается не более одной директивы #else.\n▶ Директива #else должна быть последней директивой перед\n#endif', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 17', '2026-09-29 23:43:01.773856+00', '2026-09-29 23:43:01.773856+00'),
                                                                                                                                       ('9ae457fc-414a-49f7-b18e-c104bdb6583d', 'b24951d27065b20a', 'boolean', 'Объектный файл состоит из блоков машинного кода и данных, служащих для связи с другими объектными файлами.', 'true', 'Объектный файл содержит машинный код и данные, а также таблицы символов для связей между файлами. Компоновщик использует эти сведения при сборке исполняемого файла.', E'Объектный файл представляет собой блоки машинного кода и данных, служащих для связи с другими объектными файлами.\nТаблица символов хранит:\n▶ имена переменных, функций, классов и других объектов\n▶ их типы, область видимости и размеры\n▶ информацию о данных и процедурах в других объектных файлах\nС помощью таблиц символов, компоновщик строит связи во множестве объектных файлов и объединяет их в единый исполняемый файл', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 29', '2026-09-29 23:43:01.776045+00', '2026-09-29 23:43:01.776045+00'),
                                                                                                                                       ('21484d2b-12bf-4546-b0fe-4830b287b5ac', 'b24951d27065b20a', 'choice', 'Какая структура в объектном файле хранит имена переменных, функций, классов и других объектов вместе с их типами и областью видимости?', 'Таблица символов', 'Таблица символов хранит имена объектов, их типы, область видимости и размеры, что необходимо компоновщику для сборки единого исполняемого файла.', E'Объектный файл представляет собой блоки машинного кода и данных, служащих для связи с другими объектными файлами.\nТаблица символов хранит:\n▶ имена переменных, функций, классов и других объектов\n▶ их типы, область видимости и размеры\n▶ информацию о данных и процедурах в других объектных файлах\nС помощью таблиц символов, компоновщик строит связи во множестве объектных файлов и объединяет их в единый исполняемый файл', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 29', '2026-09-29 23:43:01.778234+00', '2026-09-29 23:43:01.778234+00'),
                                                                                                                                       ('256192b3-9d11-4562-a585-126e4ac36e1e', 'b24951d27065b20a', 'flip', 'С помощью какой утилиты можно посмотреть содержимое секций объектного файла вроде .bss, .data и .text?', 'nm', 'Утилита nm позволяет узнать некоторую информацию об объектных файлах, несмотря на то что они нечитаемы человеком напрямую.', E'Объектный файл представляет собой блоки машинного кода и данных, служащих для связи с другими объектными файлами.\nТаблица символов хранит:\n▶ имена переменных, функций, классов и других объектов\n▶ их типы, область видимости и размеры\n▶ информацию о данных и процедурах в других объектных файлах\nС помощью таблиц символов, компоновщик строит связи во множестве объектных файлов и объединяет их в единый исполняемый файл', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 29', '2026-09-29 23:43:01.788309+00', '2026-09-29 23:43:01.788309+00'),
                                                                                                                                       ('b50b5c17-e16e-49c2-ac38-5f03bceb6a27', '348c4eaf7a6af5e0', 'boolean', 'На этапе ассемблирования получаемые файлы остаются легко читаемыми человеком без дополнительных инструментов.', 'false', 'Ассемблирование преобразует ассемблерный код в объектный файл; читаемость человеком теряется именно у объектного файла, который уже является бинарным.', E'Используем MinGW ассемблер as.exe, чтобы собрать объектные файлы. as.exe ./main.asm -o ./main.obj as.exe ./hello.asm -o ./hello.obj\n\nНа данном этапе получаемые файлы перестают быть читаемыми человеком', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 30', '2026-09-29 23:43:01.790535+00', '2026-09-29 23:43:01.790535+00'),
                                                                                                                                       ('6c0f6717-b060-4a81-84e3-6cc0bfb46f10', '348c4eaf7a6af5e0', 'choice', 'Какие файлы после этапа ассемблирования перестают быть читаемыми человеком?', 'Объектный файл', 'После работы as.exe получаются объектные файлы — это двоичные артефакты, которые человек напрямую читать не может.', E'Используем MinGW ассемблер as.exe, чтобы собрать объектные файлы. as.exe ./main.asm -o ./main.obj as.exe ./hello.asm -o ./hello.obj\n\nНа данном этапе получаемые файлы перестают быть читаемыми человеком', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 30', '2026-09-29 23:43:01.792699+00', '2026-09-29 23:43:01.792699+00'),
                                                                                                                                       ('00953644-a790-4a60-a6f5-c251f9e9f0ed', '348c4eaf7a6af5e0', 'input', 'Какой ассемблер упоминается как используемый для сборки объектных файлов?', 'as.exe', 'В примере используется MinGW-ассемблер as.exe для получения объектных файлов из ассемблерных исходников.', E'Используем MinGW ассемблер as.exe, чтобы собрать объектные файлы. as.exe ./main.asm -o ./main.obj as.exe ./hello.asm -o ./hello.obj\n\nНа данном этапе получаемые файлы перестают быть читаемыми человеком', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 30', '2026-09-29 23:43:01.802226+00', '2026-09-29 23:43:01.802226+00'),
                                                                                                                                       ('5e4ca3c5-167b-478c-a2b6-bc1e6184c0ad', '348c4eaf7a6af5e0', 'flip', 'Как называется этап, на котором as.exe собирает main.asm и hello.asm в object-файлы?', 'Ассемблирование', 'Именно этап ассемблирования превращает ассемблерный текст в объектный файл посредством as.exe.', E'Используем MinGW ассемблер as.exe, чтобы собрать объектные файлы. as.exe ./main.asm -o ./main.obj as.exe ./hello.asm -o ./hello.obj\n\nНа данном этапе получаемые файлы перестают быть читаемыми человеком', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 30', '2026-09-29 23:43:01.80443+00', '2026-09-29 23:43:01.80443+00'),
                                                                                                                                       ('709a23b0-84e3-4a4f-b2f6-5356d6a6db30', 'ce286ceda6b7a6fd', 'boolean', 'Компоновщик объединяет объектные файлы и статические библиотеки в единый исполняемый файл.', 'true', 'Компоновщик принимает несколько объектных файлов и формирует один исполняемый файл, пригодный к запуску.', 'Компоновщик (линкер) связывает все объектные файлы и статические библиотеки в единый исполняемый файл, который мы сможем запустить в дальнейшем. g++ ./main.obj ./hello.obj -o program.exe', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 32', '2026-09-29 23:43:01.806688+00', '2026-09-29 23:43:01.806688+00'),
                                                                                                                                       ('bcddbcb7-4619-44c6-99f2-1807077ca3ce', 'ce286ceda6b7a6fd', 'choice', 'Какая команда выполняет компоновку двух объектных файлов в единый исполняемый файл?', 'g++ ./main.obj ./hello.obj -o program.exe', 'Приведённая команда вызывает компоновщик через g++, объединяя два объектных файла в программу program.exe.', 'Компоновщик (линкер) связывает все объектные файлы и статические библиотеки в единый исполняемый файл, который мы сможем запустить в дальнейшем. g++ ./main.obj ./hello.obj -o program.exe', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 32', '2026-09-29 23:43:01.808802+00', '2026-09-29 23:43:01.808802+00'),
                                                                                                                                       ('6634efcf-7a2d-4297-a971-fc0569501717', 'ce286ceda6b7a6fd', 'input', 'Как иначе называют компоновщика, который создаёт единый исполняемый файл из нескольких объектных?', 'компоновщик (линкер)', 'Задача линкера — связать символы из разных объектных файлов и библиотек и создать готовый к запуску образ.', 'Компоновщик (линкер) связывает все объектные файлы и статические библиотеки в единый исполняемый файл, который мы сможем запустить в дальнейшем. g++ ./main.obj ./hello.obj -o program.exe', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 32', '2026-09-29 23:43:01.818434+00', '2026-09-29 23:43:01.818434+00'),
                                                                                                                                       ('61377c08-f6eb-47c9-8025-ba05f1a8ebde', 'ce286ceda6b7a6fd', 'flip', 'Что делает компоновщик согласно приведённому описанию?', 'Связывание всех объектных файлов и статических библиотек в единый исполняемый файл.', 'Это прямое назначение компоновщика по фрагменту: объединить артефакты сборки в готовую программу.', 'Компоновщик (линкер) связывает все объектные файлы и статические библиотеки в единый исполняемый файл, который мы сможем запустить в дальнейшем. g++ ./main.obj ./hello.obj -o program.exe', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 32', '2026-09-29 23:43:01.820545+00', '2026-09-29 23:43:01.820545+00'),
                                                                                                                                       ('173832e5-31d2-4b35-89a6-e420db2208ee', 'c7acc3149726df8a', 'choice', 'Какие языки приведены как примеры языков с виртуальными машинами, компилирующих в байт-код?', 'Java, C#', 'Эти языки упомянуты как использующие виртуальную машину и байт-код, обеспечивая кроссплатформенность ценой накладных расходов.', E'Языки с виртуальными машинами (Java, C#):\n▶ Компиляция в байт-код (промежуточное представление)\n▶ Виртуальная машина переводит байт-код в машинный код\n▶ Плюсы: кроссплатформенность\n▶ Минусы: больше памяти, медленнее выполнение\nИнтерпретируемые языки (JavaScript)\n▶ Выполнение кода построчно без компиляции\n▶ Плюсы: простота запуска, возможность быстро тестировать и изменять код без компиляции\n▶ Минусы: медленная скорость выполнения', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 33', '2026-09-29 23:43:01.822725+00', '2026-09-29 23:43:01.822725+00'),
                                                                                                                                       ('2af590e0-46aa-421b-b6c3-033a5c8c6b03', 'c7acc3149726df8a', 'boolean', 'У языков с виртуальными машинами (Java, C#) быстрее выполнение за счёт отсутствия интерпретации.', 'false', 'Для Java и C# указано «медленнее выполнение», поэтому утверждение неверно.', E'Языки с виртуальными машинами (Java, C#):\n▶ Компиляция в байт-код (промежуточное представление)\n▶ Виртуальная машина переводит байт-код в машинный код\n▶ Плюсы: кроссплатформенность\n▶ Минусы: больше памяти, медленнее выполнение\nИнтерпретируемые языки (JavaScript)\n▶ Выполнение кода построчно без компиляции\n▶ Плюсы: простота запуска, возможность быстро тестировать и изменять код без компиляции\n▶ Минусы: медленная скорость выполнения', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 33', '2026-09-29 23:43:01.832344+00', '2026-09-29 23:43:01.832344+00'),
                                                                                                                                       ('2eb9daf0-7024-44b8-b4ea-b34f910c3675', 'c7acc3149726df8a', 'flip', 'Какие плюсы указаны у интерпретируемых языков наподобие JavaScript?', 'простота запуска, возможность быстро тестировать и изменять код без компиляции', 'Так сформулированы плюсы интерпретируемых языков в тексте.', E'Языки с виртуальными машинами (Java, C#):\n▶ Компиляция в байт-код (промежуточное представление)\n▶ Виртуальная машина переводит байт-код в машинный код\n▶ Плюсы: кроссплатформенность\n▶ Минусы: больше памяти, медленнее выполнение\nИнтерпретируемые языки (JavaScript)\n▶ Выполнение кода построчно без компиляции\n▶ Плюсы: простота запуска, возможность быстро тестировать и изменять код без компиляции\n▶ Минусы: медленная скорость выполнения', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 33', '2026-09-29 23:43:01.834421+00', '2026-09-29 23:43:01.834421+00'),
                                                                                                                                       ('84e7ec8d-3884-44dc-9e77-46685b77cdbe', 'c7acc3149726df8a', 'input', 'К какому классу относится JavaScript в приведённой классификации?', 'интерпретируемые языки', 'Текст прямо относит JavaScript к интерпретируемым языкам с построчным выполнением.', E'Языки с виртуальными машинами (Java, C#):\n▶ Компиляция в байт-код (промежуточное представление)\n▶ Виртуальная машина переводит байт-код в машинный код\n▶ Плюсы: кроссплатформенность\n▶ Минусы: больше памяти, медленнее выполнение\nИнтерпретируемые языки (JavaScript)\n▶ Выполнение кода построчно без компиляции\n▶ Плюсы: простота запуска, возможность быстро тестировать и изменять код без компиляции\n▶ Минусы: медленная скорость выполнения', 'Этапы обработки кода программы на C++_ пространства имён и локали, стр. 33', '2026-09-29 23:43:01.836646+00', '2026-09-29 23:43:01.836646+00'),
                                                                                                                                       ('4e402054-b545-492c-9b57-edebdcd48d4b', 'ed3eeeb764fffbaf', 'boolean', 'На интервале [0°, 90°] функция sin α возрастает, cos α убывает, tg α возрастает, ctg α убывает.', 'true', 'На [0°,90°] синус возрастает от 0 до 1, косинус убывает от 1 до 0; тангенс растёт, котангенс убывает. Это согласуется с приведёнными неравенствами.', E'β > α, тогда tg возрастает ctg убывает\n\n0 ≤ sin α < sin β ≤ 1 sin возрастает 1 ≥ cos α > cos β ≥ 0 cos убывает 0 ≤ tg α < tg β tg возрастает ctg α > ctg β > 0 ctg убывает', 'Геометрия, стр. 1', '2026-09-29 23:50:42.415185+00', '2026-09-29 23:50:42.415185+00'),
                                                                                                                                       ('a83a5a4e-afcc-454c-ac0c-ee28eab19d18', 'ed3eeeb764fffbaf', 'input', 'Какая тригонометрическая функция возрастает на всём отрезке [0°, 90°]?', 'sin α', 'Конспект фиксирует монотонность функций на [0°,90°]: из перечисленных именно sin α возрастает.', E'β > α, тогда tg возрастает ctg убывает\n\n0 ≤ sin α < sin β ≤ 1 sin возрастает 1 ≥ cos α > cos β ≥ 0 cos убывает 0 ≤ tg α < tg β tg возрастает ctg α > ctg β > 0 ctg убывает', 'Геометрия, стр. 1', '2026-09-29 23:50:42.416903+00', '2026-09-29 23:50:42.416903+00'),
                                                                                                                                       ('8a410072-f19a-4337-a6ad-526169d9fd29', '20e18d0b841dc55d', 'boolean', 'cos(180° − α) = −cos α и sin(180° − α) = sin α.', 'true', 'Формулы приведения для тупого угла приведены явно: cos(180°−α)=−cos α, sin(180°−α)=sin α.', 'cos (180° - α) = -cos α sin (180° - α) = sin α', 'Геометрия, стр. 2', '2026-09-29 23:50:42.418348+00', '2026-09-29 23:50:42.418348+00'),
                                                                                                                                       ('be961daa-fd0f-43e7-9b1a-660f272499d9', '86d0d4fcc8866b01', 'choice', 'Чем измеряется угол между касательной и хордой, проведённой в точку касания?', 'Половиной дуги', 'Теорема сформулирована буквально: угол между касательной и хордой измеряется половиной заключённой внутри дуги.', 'Угол между касательной и хордой измеряется половиной дуги заключенной внутри угла', 'Геометрия, стр. 3', '2026-09-29 23:50:42.419785+00', '2026-09-29 23:50:42.419785+00'),
                                                                                                                                       ('ae9d3c64-249e-4172-860e-712630e4c74d', '86d0d4fcc8866b01', 'flip', 'Сформулируйте теорему об угле между касательной и хордой.', 'Угол между касательной и хордой измеряется половиной дуги, заключённой внутри угла.', 'Это прямая формулировка теоремы из фрагмента; она связывает величину угла с дугой окружности.', 'Угол между касательной и хордой измеряется половиной дуги заключенной внутри угла', 'Геометрия, стр. 3', '2026-09-29 23:50:42.426849+00', '2026-09-29 23:50:42.426849+00'),
                                                                                                                                       ('f7db1cff-b696-4e4f-8ece-60eda57ac350', '86d0d4fcc8866b01', 'boolean', 'Угол между касательной и хордой равен дуге, заключённой внутри угла.', 'false', 'В утверждении говорится ''равен дуге'', но по тексту — половине дуги.', 'Угол между касательной и хордой измеряется половиной дуги заключенной внутри угла', 'Геометрия, стр. 3', '2026-09-29 23:50:42.428189+00', '2026-09-29 23:50:42.428189+00'),
                                                                                                                                       ('f3865161-02b6-4863-8755-d9b5760dce59', '977aafecd90380d9', 'flip', 'Опишите первый шаг построения точки B при решении задачи о трапеции по четырём сторонам.', 'Проводят окружности ω₁(C; R=b) и ω₂(D; R=c); их пересечение — точка B.', 'Это первый шаг построения после анализа: задают центры C и D и радиусы b и c, получая вершину B.', E'Анализ:\nЗадача сводится к построению Δ ВСК по трём сторонам b, c, d=a.\nПостроение:\n2. Окр. ω₁(C; R=b), окр. ω₂(D; R=c), ω₁∩ω₂=B.\n3. Окр. ω₃(K), окр. ω₄(D; R=c), ω₃∩ω₄=A.\n4. ABCD - искомая трапеция.\nДоказательство:\n4. ABCD - искомая трапеция\n\nДоказательство:\n1. АВ=a, CD=d, BC=b, AD=c - по построению\n2. АВ=DK, AD=BK - по построению, тогда ABDK - парал., тогда АВ||DC. Тогда ABCD - трапеция.\nСледствие: Задача имеет единственное решение при условии выполнимости неравенства треугольника для a,b,c,d-a', 'Геометрия, стр. 4', '2026-09-29 23:50:42.429457+00', '2026-09-29 23:50:42.429457+00'),
                                                                                                                                       ('adaa55e4-3bb3-4d6c-b55f-599f6131d02b', '977aafecd90380d9', 'boolean', 'При выполнимости неравенства треугольника для заданных длин решение задачи о трапеции по четырём сторонам единственно.', 'true', 'Текст утверждает единственность решения при выполнении неравенства треугольника для сторон.', E'Анализ:\nЗадача сводится к построению Δ ВСК по трём сторонам b, c, d=a.\nПостроение:\n2. Окр. ω₁(C; R=b), окр. ω₂(D; R=c), ω₁∩ω₂=B.\n3. Окр. ω₃(K), окр. ω₄(D; R=c), ω₃∩ω₄=A.\n4. ABCD - искомая трапеция.\nДоказательство:\n4. ABCD - искомая трапеция\n\nДоказательство:\n1. АВ=a, CD=d, BC=b, AD=c - по построению\n2. АВ=DK, AD=BK - по построению, тогда ABDK - парал., тогда АВ||DC. Тогда ABCD - трапеция.\nСледствие: Задача имеет единственное решение при условии выполнимости неравенства треугольника для a,b,c,d-a', 'Геометрия, стр. 4', '2026-09-29 23:50:42.430716+00', '2026-09-29 23:50:42.430716+00')
