-- Все пользователи -> на каждый набор
-- +goose StatementBegin
SELECT u.id, s.id, now()
FROM public.users u
         CROSS JOIN public.sets s
WHERE s.id IN ('6d12ca92-e5ba-4808-946e-17b207765a72', '104d6ef5-2d2b-451b-9ae4-07ec047600f5', 'a782a18c-b664-41c6-8a8c-9842393d3f4f')
    ON CONFLICT DO NOTHING;
-- +goose StatementEnd

-- Случайный elo (600..1400) по каждому факту каждого набора для каждого пользователя
-- +goose StatementBegin
 interval_days, ease_factor, next_review_at, last_reviewed_at)
SELECT us.user_id, f.id, 600 + floor(random() * 801)::int, false, 0, 0, 0, 2.50, now(), NULL
FROM public.user_sets us
         JOIN public.facts f ON f.set_id = us.set_id
WHERE us.set_id IN ('6d12ca92-e5ba-4808-946e-17b207765a72', '104d6ef5-2d2b-451b-9ae4-07ec047600f5', 'a782a18c-b664-41c6-8a8c-9842393d3f4f')
    ON CONFLICT DO NOTHING;
-- +goose StatementEnd

